// Normaliza: cualquier valor distinto de OFF → ON (fail-safe: seguir cargando)
const want = String(msg.payload).trim().toUpperCase() === 'OFF' ? 'OFF' : 'ON';
const on = want === 'ON';
const type = (env.get('PLUG_TYPE') || 'dry-run').trim();
const host = (env.get('PLUG_HOST') || '').trim();
const topic = (env.get('PLUG_MQTT_TOPIC') || 'tasmota_plug').trim();
flow.set('wanted', want);
flow.set('wanted_ts', Date.now());
flow.set('wanted_reason', msg.reason || '');
node.status({ fill: on ? 'green' : 'grey', shape: 'dot', text: type + ': ' + want + (msg.reason ? ' (' + msg.reason + ')' : '') });
// Salidas: 1 = comando MQTT, 2 = petición HTTP, 3 = dry-run/log, 4 = consulta MQTT (sin espera de confirmación)
const ch = String(env.get('PLUG_CHANNEL') || '1').trim();
switch (type) {
  case 'openbeken-mqtt':
    // OpenBeken: <topic>/<canal>/set 1|0; el «get» vacío pide que publique <topic>/<canal>/get (confirmación
    // aunque el relé ya estuviera en ese estado y no haya cambio que publicar)
    return [{ topic: topic + '/' + ch + '/set', payload: on ? '1' : '0', retain: false, want }, null, null,
            { topic: topic + '/' + ch + '/get', payload: '', retain: false }];
  case 'tasmota-mqtt':
    return [{ topic: 'cmnd/' + topic + '/POWER', payload: want, retain: false, want }, null, null];
  case 'shelly-gen2-mqtt':
    return [{ topic: topic + '/command/switch:0', payload: on ? 'on' : 'off', retain: false, want }, null, null];
  case 'tasmota-http':
    return [null, { url: 'http://' + host + '/cm?cmnd=Power%20' + (on ? 'On' : 'Off'), want, plugType: type }, null];
  case 'shelly-gen2-http':
    return [null, { url: 'http://' + host + '/rpc/Switch.Set?id=0&on=' + on, want, plugType: type }, null];
  case 'shelly-gen1-http':
    return [null, { url: 'http://' + host + '/relay/0?turn=' + (on ? 'on' : 'off'), want, plugType: type }, null];
  case 'dry-run':
    return [null, null, { payload: '[dry-run] enchufe → ' + want, want }];
  default:
    node.warn('PLUG_TYPE desconocido: ' + type);
    return [null, null, { payload: 'PLUG_TYPE desconocido: ' + type, want, alert: true }];
}

// Respuesta HTTP del enchufe → estado real. Salidas: 1 = plug_state, 2 = reset espera, 3 = alerta
const want = msg.want || flow.get('wanted') || 'ON';
// Error de red: el nodo http request también reenvía el msg (statusCode = 'ECONNREFUSED'…);
// la alerta ya la emite el nodo catch → aquí solo estado ERROR
if (typeof msg.statusCode !== 'number') {
  return [{ payload: 'ERROR' }, { reset: true }, null];
}
if (msg.statusCode < 200 || msg.statusCode >= 300) {
  return [{ payload: 'ERROR' }, { reset: true }, { payload: 'Enchufe HTTP ' + msg.statusCode + ' (' + msg.url + ')' }];
}
let body = msg.payload;
try { if (typeof body === 'string') body = JSON.parse(body); } catch (e) { body = {}; }
let actual = null;
if (body && typeof body.POWER === 'string') actual = body.POWER.toUpperCase();      // Tasmota
else if (body && typeof body.ison === 'boolean') actual = body.ison ? 'ON' : 'OFF';  // Shelly Gen1
else actual = want;                                                                    // Shelly Gen2 (was_on) → asumimos orden aplicada
if (actual !== want) {
  return [{ payload: actual }, { reset: true }, { payload: 'Enchufe responde ' + actual + ' pero se pidió ' + want }];
}
return [{ payload: actual }, { reset: true }, null];

node.status({ fill: 'blue', shape: 'ring', text: msg.payload });
const out = [{ payload: 'DRYRUN-' + msg.want }, null];
if (msg.alert) out[1] = { payload: msg.payload };
return out;

// Estado publicado por el enchufe (Tasmota stat/<topic>/POWER, Shelly Gen2 <id>/status/switch:0,
// OpenBeken <topic>/<canal>/get con 0|1)
const ch = String(env.get('PLUG_CHANNEL') || '1').trim();
const topic = (env.get('PLUG_MQTT_TOPIC') || 'tasmota_plug').trim();
const type = (env.get('PLUG_TYPE') || 'dry-run').trim();
let actual = null;
if (type === 'openbeken-mqtt' && msg.topic === topic + '/' + ch + '/get') {
  const v = String(msg.payload).trim();
  if (!/^-?[0-9]+$/.test(v)) return null;   // nuestra propia consulta vacía
  actual = Number(v) !== 0 ? 'ON' : 'OFF';
} else if (type === 'tasmota-mqtt' && msg.topic === 'stat/' + topic + '/POWER') {
  actual = String(msg.payload).toUpperCase();
} else if (type === 'shelly-gen2-mqtt' && msg.topic === topic + '/status/switch:0') {
  let p = msg.payload;
  try { if (typeof p === 'string') p = JSON.parse(p); } catch (e) { return null; }
  if (p && typeof p.output === 'boolean') actual = p.output ? 'ON' : 'OFF';
}
if (!actual) return null;
const want = flow.get('wanted');
const out = [{ payload: actual }, { reset: true }, null];
if (want && actual !== want && Date.now() - (flow.get('wanted_ts') || 0) < 120000) {
  out[2] = { payload: 'Enchufe informa ' + actual + ' pero se pidió ' + want };
}
return out;

// Sin latido del limitador → fail-safe: enchufe ON (el móvil no se queda sin batería)
return [{ payload: 'ON', reason: 'watchdog' },
        { payload: 'Sin latido de charge-limiter en 15 min → enchufe ON (fail-safe). ¿Termux/servicio caído?' }];

// Publica alerta retenida para el móvil (charge-limiter la lee y lanza termux-notification)
const text = msg.error ? ('Error enchufe: ' + (msg.error.message || msg.error)) : String(msg.payload);
node.warn(text);
node.status({ fill: 'red', shape: 'ring', text: text.substring(0, 40) });
return { topic: 'gt2/power/charger/alert', retain: true,
         payload: JSON.stringify({ ts: Math.floor(Date.now() / 1000), msg: text, source: 'node-red' }) };
